import json

class LibrarySystem:
    def __init__(self):
        self.books = []
        self.members = []
        self.libraries = {}

    def add_book(self, book):
        self.books.append(book)
        self.save_books()

    def save_books(self):
        data = {
            "books": self.books
        }
        self.libraries["books"] = data
        self.books = []

    def add_member(self, member):
        self.members.append(member)
        self.save_members()

    def save_members(self):
        data = {
            "members": self.members
        }
        self.libraries["members"] = data
        self.members = []

    def borrow_book(self, member, book):
        if member not in self.members:
            return "Member not found."
        if book not in self.books:
            return "Book not found."
        self.books.remove(book)
        self.save_books()
        self.save_members()
        return f"Book {book} borrowed by {member}."

    def return_book(self, member, book):
        if member not in self.members:
            return "Member not found."
        if book not in self.books:
            return "Book not found."
        self.books.append(book)
        self.save_books()
        self.save_members()
        return f"Book {book} returned by {member}."

    def list_books(self):
        return json.dumps(self.libraries["books"], indent=4)

    def list_members(self):
        return json.dumps(self.libraries["members"], indent=4)

    def list_all(self):
        return json.dumps(self.libraries, indent=4)

if __name__ == "__main__":
    library = LibrarySystem()
    library.add_book({"title": "Python Programming", "author": "John Doe"})
    library.add_member({"name": "Alice", "age": 25})
    library.add_member({"name": "Bob", "age": 30})
    library.borrow_book("Alice", "Python Programming")
    print(library.list_books())
    print(library.list_members())
    print(library.borrow_book("Alice", "Python Programming"))
    print(library.return_book("Alice", "Python Programming"))
    print(library.list_books())
    print(library.list_members())
    print(library.list_all())
```

